            .then(r =&gt; r.json())
            .then(resultados =&gt; {
                listaDiv.innerHTML = &#039;&#039;;
                if (resultados.length === 0) {
                    listaDiv.innerHTML = &#039;&lt;span class=&quot;list-group-item text-muted&quot;&gt;Sin resultados&lt;/span&gt;&#039;;
