    document.addEventListener(&#039;click&#039;, function(e) {
        if (listaAut &amp;&amp; !listaAut.contains(e.target) &amp;&amp; e.target.id !== &#039;buscarApellidoAut&#039; &amp;&amp; e.target.id !== &#039;btnBuscarApellidoAut&#039;) {
            listaAut.style.display = &#039;none&#039;;
        }
